try {
  const raw = localStorage.getItem(STORAGE_KEY);
  const parsed = raw ? JSON.parse(raw) : [];
  transactions = Array.isArray(parsed) ? parsed : [];
} catch (error) {
  transactions = [];
}
return transactions;

if (!Number.isInteger(index) || index < 0 || index >= transactions.length) {
  return;
}
transactions.splice(index, 1);
saveTransactions();
render();

.chart-row {
  display: grid;
  grid-template-columns: 110px 1fr 90px;
  align-items: center;
  gap: 10px;
  margin: 10px 0;
}
.chart-track {
  height: 18px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}
.chart-fill {
  display: block;
  height: 100%;
  width: 0%;
  background: #2563eb;
}

const chartIncome = transactions
  .filter((item) => item.type === 'income' || item.tipo === 'receita')
  .reduce((sum, item) => sum + Number(item.value || item.valor || 0), 0);
const chartExpense = transactions
  .filter((item) => item.type === 'expense' || item.tipo === 'despesa')
  .reduce((sum, item) => sum + Number(item.value || item.valor || 0), 0);
const chartMax = Math.max(chartIncome, chartExpense, 1);
const incomeFill = document.getElementById('chart-income-fill');
const expenseFill = document.getElementById('chart-expense-fill');
const incomeValue = document.getElementById('chart-income-value');
const expenseValue = document.getElementById('chart-expense-value');
if (incomeFill) incomeFill.style.width = `${Math.round((chartIncome / chartMax) * 100)}%`;
if (expenseFill) expenseFill.style.width = `${Math.round((chartExpense / chartMax) * 100)}%`;
if (incomeValue) incomeValue.textContent = money(chartIncome);
if (expenseValue) expenseValue.textContent = money(chartExpense);

if (!Number.isInteger(index) || index < 0 || index >= transactions.length) {
  return;
}
transactions.splice(index, 1);
saveTransactions();
render();
